INSERT OR REPLACE INTO prompts (id, source, source_url, title, abstract, prompt_text, negative_prompt, category, style, model, image_url, width, height, tags, collected_at) VALUES ('prmpt:greek-ruins-wet-dress', 'prmpt', 'https://prmpt.it.com/prompt/greek-ruins-wet-dress', 'Greek Ruins - Ethereal Portrait', 'Ethereal portrait in flooded ancient Greek ruins with wet draped dress. Perfect for mythological art, cinematic portraits, and fantasy-inspired fashion.', '{
  "image_generation_prompt": {
    "subject": {
