INSERT OR REPLACE INTO prompts (id, source, source_url, title, abstract, prompt_text, negative_prompt, category, style, model, image_url, width, height, tags, collected_at) VALUES ('prmpt:asian-model-avant-garde-2', 'prmpt', 'https://prmpt.it.com/prompt/asian-model-avant-garde-2', 'Asian Model - Avant-Garde Editorial 2', 'Generate vintage-inspired fashion photography for apparel brands, editorial shoots, and marketing materials. Advanced lighting setup suitable for professional use.', 'A high-fashion editorial series featuring a stunning Asian female model with sculptural features and porcelain skin, captured in full-body and close-up shots across various dynamic poses and movements. Styled in avant-garde, architectural couture with bold silhouettes and flowing fabrics. The setting is a minimalist photo studio with textured concrete floors and soft neutral backdrops. Include shots of the model in motion—leaping, walking with motion blur, twisting mid-air, and crouching center frame—as well as moments of stillness with close-ups of hands, face, and sculptural poses on the ground. Play with composition: overhead shots, profile views, cropped torso with gestural hands. Emphasize directionality and elegance in her movements. Lighting is cinematic and stylized: a mix of soft spotlight, strong rim/backlight for silhouette, gentle window light, and occasional lens flare. Style the series with a subtle analog film aesthetic: fine grain, muted color tones, soft haze, gentle vignetting, and a timeless mood. Depth of field varies—some images with crisp focus, others with soft bokeh or blur in motion. Captured in the style of a luxury fashion magazine editorial—bold, soulful, and intentional. Stylized but never artificial. Studio-based, fashion-forward, emotionally rich.', NULL, 'fashion', 'portrait', NULL, 'https://storage.googleapis.com/prmpt-58b35.firebasestorage.app/prompts/asian-model-avant-garde-2.webp', NULL, NULL, '[]', '1792931362731');
