INSERT OR REPLACE INTO prompts (id, source, source_url, title, abstract, prompt_text, negative_prompt, category, style, model, image_url, width, height, tags, collected_at) VALUES ('prmpt:color-box-editorial-fashion-male', 'prmpt', 'https://prmpt.it.com/prompt/color-box-editorial-fashion-male', 'Color Box - Editorial Fashion I', 'Surreal 3D color box high-fashion editorial with geometric framing and bold colors. Perfect for avant-garde fashion campaigns, creative editorial shoots, and modern menswear content.', '[INPUT IMAGE: USER_PHOTO OR YOUR PERSONA] Use the person in the input image as the ONLY subject. Preserve their identity and facial features clearly. Create a hyper-realistic high-fashion editorial photo inside a surreal 3D geometric "color box" room (a hollow cube / tilted cube set). Each render MUST randomly choose: a bold single-color box (monochrome environment, vivid and saturated), a dynamic "cool" fashion pose (gravity-defying or extreme stretch / leap / sideways bracing against the walls), a dramatic camera angle (wide-angle 24–35mm equivalent, tilted horizon, strong perspective). The subject appears full-body and sharp, wearing contemporary high-end fashion with a strong, structured silhouette — tailored designer pieces, modern luxury streetwear or elevated minimalist styling. Think sharp tailoring, premium textures, clean lines, refined layering, confident masculine energy. Avoid flamboyant, androgynous, exaggerated or theatrical styling. Focus on sleek, powerful, fashion-forward but grounded aesthetics (editorial menswear direction, structured jacket, refined trousers, premium sneakers or boots). The subject''s pose should feel athletic, stylish, and unusual—like a magazine campaign shot. Lighting: studio quality, crisp and cinematic; strong key light with controlled soft shadows, subtle rim light; realistic reflections and bounce light from the colored walls. Ultra-detailed skin texture, natural pores, realistic fabric weave, clean edges, high dynamic range. Composition: subject centered with plenty of negative space and strong geometric lines; the box perspective frames the subject. Color: the box color is a SINGLE bold color and MUST be different each run (random vivid hue). The subject''s outfit contrasts well with the box color. Output: hyper-real, photorealistic, 8k detail, editorial campaign quality, sharp focus on subject, no motion blur, no distortion of face, natural proportions.', NULL, 'fashion', 'portrait', NULL, 'https://storage.googleapis.com/prmpt-58b35.firebasestorage.app/prompts/color-box-editorial-fashion-male.webp', NULL, NULL, '[]', '1792931387514');
