INSERT OR REPLACE INTO prompts (id, source, source_url, title, abstract, prompt_text, negative_prompt, category, style, model, image_url, width, height, tags, collected_at) VALUES ('prmpt:iceland-volcanic-beach-2', 'prmpt', 'https://prmpt.it.com/prompt/iceland-volcanic-beach-2', 'Iceland - Volcanic Beach 2', 'Generate modern landscape photography for tourism boards, adventure brands, and creative portfolios. Golden hour techniques showcases stunning natural scenes.', 'A candid, spontaneous iPhone snapshot of a European woman with model-like features seated on the black volcanic sand beach in Iceland. She wears an all-black outdoor ensemble consisting of a technical shell jacket, cargo pants, sturdy hiking boots, and a fitted black beanie. Her thoughtful gaze directed sideways conveys quiet contemplation. The dark outfit subtly blends with the coarse volcanic sand beneath her, as chunks of clear, glistening ice and scattered gray stones punctuate the foreground. Behind her, the wide Icelandic coastline unfolds with gently breaking white waves and a vast moody ocean stretching to the horizon. Soft, overcast natural daylight gently illuminates the scene, emphasizing nuanced textures: the gritty volcanic sand grains, the smooth transparency of ice, the durable technical fabric surfaces, and subtle water reflections. The composition is wide and casually framed with a slight tilt, expressing raw minimalism and cinematic authenticity typical of an intimate travel moment captured spontaneously on an iPhone.', NULL, 'landscape', 'landscape', NULL, 'https://storage.googleapis.com/prmpt-58b35.firebasestorage.app/prompts/iceland-volcanic-beach-2.webp', NULL, NULL, '[]', '1792931532332');
