INSERT OR REPLACE INTO prompts (id, source, source_url, title, abstract, prompt_text, negative_prompt, category, style, model, image_url, width, height, tags, collected_at) VALUES ('prmpt:arsenal-lingerie-rifles-bw', 'prmpt', 'https://prmpt.it.com/prompt/arsenal-lingerie-rifles-bw', 'Arsenal Lingerie - Rifles B&amp;W', 'Bold cinematic black and white with edgy urban aesthetic. Perfect for alternative fashion, graphic design, and provocative editorial content.', 'Hyper-realistic black-and-white photograph of a woman standing confidently with her back to the viewer in an underground urban hideout. She is wearing sleek, form-fitting lingerie with a garter belt and thigh-high stockings, tastefully framed with no nudity. In her right hand she holds a futuristic AR-style assault rifle pointed down at her side. The wall in front of her is covered with neatly arranged rifles and guns, like a private arsenal. High-contrast, dramatic lighting from above and slightly behind sculpts her silhouette and the weapons, creating deep shadows and bright highlights. The scene feels gritty and cinematic, inspired by street culture and vintage pin-up photography, with a bold, edgy, provocative but non-explicit mood. Shot on a high-end full-frame camera, ultra-detailed, realistic textures, sharp focus, perfect for a striking T-shirt design.', NULL, 'lingerie', 'cinematic', NULL, 'https://storage.googleapis.com/prmpt-58b35.firebasestorage.app/prompts/arsenal-lingerie-rifles-bw.webp', NULL, NULL, '[]', '1792932039863');
INSERT OR REPLACE INTO prompts (id, source, source_url, title, abstract, prompt_text, negative_prompt, category, style, model, image_url, width, height, tags, collected_at) VALUES ('prmpt:bathroom-corset-noir-dramatic', 'prmpt', 'https://prmpt.it.com/prompt/bathroom-corset-noir-dramatic', 'Bathroom Corset - Noir Dramatic', 'Dramatic noir bathroom boudoir with intense lighting. Perfect for luxury lingerie campaigns, sensual fashion editorials, and artistic intimate photography.', 'In a dimly lit hotel bathroom, muted shadows envelop a young woman poised in a dramatic arched-back posture atop a cool marble counter. Her slim figure is adorned with a black lace corset dress featuring garter straps and thigh-high stockings, complemented subtly by sparkling black crystal jewelry reminiscent of Chanel elegance. Harsh, low-key lighting carves a narrow, focused beam across her torso, intensifying the intricate lace texture and casting deep shadows that retreat softly into the high-contrast monochrome palette. Her hands grip the counter firmly, body stretched in tension, while a mirror reflects fragments of the scene, adding spatial depth and intrigue. The shallow focus draws the eye sharply to her sleek corset, while glossy makeup enhances the sensual noir mood, captured through a standard lens with delicate shadow falloff and fine grain. The overall composition centers the subject in a medium-full shot, her head tilted gracefully upward, embodying a luxurious, intimate boudoir editorial.', NULL, 'lingerie', 'noir', NULL, 'https://storage.googleapis.com/prmpt-58b35.firebasestorage.app/prompts/bathroom-corset-noir-dramatic.webp', NULL, NULL, '[]', '1792932041421');
INSERT OR REPLACE INTO prompts (id, source, source_url, title, abstract, prompt_text, negative_prompt, category, style, model, image_url, width, height, tags, collected_at) VALUES ('prmpt:bathroom-towel-selfie', 'prmpt', 'https://prmpt.it.com/prompt/bathroom-towel-selfie', 'Bathroom - Towel Selfie', 'Casual intimate lifestyle photography for bathroom product campaigns, wellness content, and authentic social media imagery.', 'SHOT: • Composition: Medium shot, rear angle, subject centered in mirror • Camera Settings: Smartphone camera, moderate ISO, auto-focus • Film Grain: None LENS EFFECTS: • Optics: Moderate wide angle, slight distortion • Artifacts: Digital noise minimal, reflection clarity • Depth of Field: Deep focus throughout mirror and room SUBJECT: • Description: Young Caucasian female, slim body type, long loose hair • Wardrobe: White bath towel wrapped around waist, bare back exposed • Grooming: Hair wet or damp, natural loose style SCENE: • Location: Indoor bathroom with beige walls • Time of Day: Indeterminate, artificial lighting • Environment: Shower with glass door and metal frame, toiletries visible VISUAL DETAILS: • Action: Subject taking mirror selfie with smartphone held up • Props: Smartphone, shower door, toiletries on ledge • Physics: Reflections consistent, natural light physics CINEMATOGRAPHY: • Lighting: Warm, diffuse indoor light • Tone: Casual, intimate • Color Palette: Beige, white, natural skin tones TEXT ELEMENTS: • Visible Text: None • Typography: None • Placement: None STYLE: • Visual Aesthetic: Candid, everyday snapshot', NULL, 'lingerie', 'other', NULL, 'https://storage.googleapis.com/prmpt-58b35.firebasestorage.app/prompts/bathroom-towel-selfie.webp', NULL, NULL, '[]', '1792932042981');
