INSERT OR REPLACE INTO prompts (id, source, source_url, title, abstract, prompt_text, negative_prompt, category, style, model, image_url, width, height, tags, collected_at) VALUES ('prmpt:bedroom-towel-minimalist-boudoir', 'prmpt', 'https://prmpt.it.com/prompt/bedroom-towel-minimalist-boudoir', 'Bedroom Towel - Minimalist Boudoir', 'Soft low-angle boudoir of a woman in a white terrycloth towel kneeling in a minimalist bedroom. Perfect for intimate spa-inspired content, serene wellness photography, and tranquil sensual editorials.', 'A low-angle medium shot captures a young adult Caucasian woman with long, straight hair flowing over her shoulder, kneeling on a neatly made bed. She is dressed in a bright white terrycloth towel wrapped around her body, its textured fibers giving a soft, plush appearance. The woman appears relaxed and introspective, with her head angled down and her profile in partial shadow. The setting is a minimalist modern bedroom; the headboard and wall are clad in light, quilted fabric, and a smooth marble accent wall is visible beside her. Ambient daylight bathes the room, creating diffuse, shadowless lighting and a warm tone across her skin. The overall palette features clean whites and beige, contributing to a neutral, serene atmosphere. The composition centers her body in a diagonal pose, with the frame cropping above her knees and midway up her arms. Captured with a high-resolution digital camera, the image has a slight warm tint, likely enhanced in post-processing, with minimal visual noise and a soft, sensual, and tranquil mood. HEX VALUES: ["#a18874", "#582f1c", "#8f715c", "#e6d4c2", "#897d74", "#b09986", "#d8c0ab", "#826451", "#c7ac95", "#999da7", "#9faaba", "#22100b", "#724631", "#bdb2a8", "#918d8e"]', NULL, 'lingerie', 'minimalist', NULL, 'https://storage.googleapis.com/prmpt-58b35.firebasestorage.app/prompts/bedroom-towel-minimalist-boudoir.webp', NULL, NULL, '[]', '1792932047674');
