INSERT OR REPLACE INTO prompts (id, source, source_url, title, abstract, prompt_text, negative_prompt, category, style, model, image_url, width, height, tags, collected_at) VALUES ('prmpt:california-vintage-bikini-car', 'prmpt', 'https://prmpt.it.com/prompt/california-vintage-bikini-car', 'California Vintage - Bikini &amp; Car', 'Vintage California lifestyle photography for retro campaigns, automotive content, and nostalgic swimwear imagery.', 'A young Caucasian woman, embodying the relaxed glamour of late-70s California, stands poised in the open doorway of a vintage white sports car—an elegant silhouette against the endless ocean fading into dusk. Her average frame is clad in a simple white bikini, its minimal lines capturing a natural ease that contrasts with the car''s sleek retro curves and gleaming chrome accents. Loose waves of long brown hair, framed by soft curtain bangs, catch the fading sunlight, bringing warmth to her chestnut tones as a gentle coastal breeze stirs her locks. Her gaze is steady yet contemplative, cast toward the horizon with a subtle chin tilt that elongates her profile into the soft expanse of sea and sky. The setting is infused with a light that flirts between golds and cool shadows, characteristic of the sun dipping just past its peak. A casually draped jacket hangs from the door frame, lending a lived-in moment suspended between a drive and a daydream. Around her, the pastel-hued sky fades into lavender, complementing the shimmering ocean and the reflecting chrome of the car. The tactile softness of 35mm film grain overlays the scene, edges smoothly blurred and colors muted into a gentle palette that romanticizes both subject and setting. The horizon line stretches faintly, enhancing a sense of unfettered freedom and quiet introspection. Captured at eye level with a 50mm lens, the composition balances intimacy and expanse, framed through a lens mindful of vintage analog textures and era-correct analog warmth, recalling the cinematic glamour and candid nostalgia of late-70s California coastal photography. —late-70s / early-80s cinematic photograph, authentic film grain.', NULL, 'lingerie', 'other', NULL, 'https://storage.googleapis.com/prmpt-58b35.firebasestorage.app/prompts/california-vintage-bikini-car.webp', NULL, NULL, '[]', '1792932060206');
INSERT OR REPLACE INTO prompts (id, source, source_url, title, abstract, prompt_text, negative_prompt, category, style, model, image_url, width, height, tags, collected_at) VALUES ('prmpt:cinematic-bedroom-lace', 'prmpt', 'https://prmpt.it.com/prompt/cinematic-bedroom-lace', 'Cinematic Bedroom - Lace Lingerie', 'Tasteful intimate photography prompt for intimate apparel, product catalogs, and boudoir portfolios. Soft lighting creates alluring imagery.', 'A softly lit cinematic scene in a dimly glowing bedroom, warm amber light spilling through sheer curtains. lula stands near the window, wearing elegant lace lingerie beneath a loose silk robe, her hair gently tousled. The focus is on emotion and atmosphere — longing, intimacy, and tenderness — rather than exposure. The composition feels like a movie still, with shallow depth of field, moody light, and the sense of a quiet moment between love and desire.', NULL, 'lingerie', 'other', NULL, 'https://storage.googleapis.com/prmpt-58b35.firebasestorage.app/prompts/cinematic-bedroom-lace.webp', NULL, NULL, '[]', '1792932061781');
INSERT OR REPLACE INTO prompts (id, source, source_url, title, abstract, prompt_text, negative_prompt, category, style, model, image_url, width, height, tags, collected_at) VALUES ('prmpt:colored-light-bodysuit', 'prmpt', 'https://prmpt.it.com/prompt/colored-light-bodysuit', 'Colored Light - Bodysuit', 'Artistic fashion photography with dual-tone colored lighting. Perfect for editorial fashion, creative portraits, and cinematic mood photography.', 'SHOT: • Composition: Medium full shot, low angle, subject centered in frame • Camera Settings: ISO 400, f/3.5, 1/125 s • Film Grain: Soft grain LENS EFFECTS: • Optics: Slight vignette, slight soft focus on edges • Artifacts: None • Depth of Field: Shallow, focused on face and upper body SUBJECT: • Description: Young Caucasian female, average body type, closed eyes, lips slightly parted, contemplative expression • Wardrobe: White off-shoulder mesh bodysuit, black high heel shoes • Grooming: Medium-length wavy hair dyed with red and blue lighting highlights, bold dark lipstick SCENE: • Location: Minimalistic indoor studio, plain background • Time of Day: Indeterminate studio lighting • Environment: Neutral with colored light sources VISUAL DETAILS: • Action: Kneeling on one knee with other leg bent, one hand resting near collarbone, head slightly tilted • Props: None • Physics: Soft shadows, colored rim lighting creating glow and silhouette effects CINEMATOGRAPHY: • Lighting: Dual tone—red warm light from left, blue cool light from right, soft and dramatic • Tone: Sensual and moody • Color Palette: Deep reds, teal blues, neutral skin tones TEXT ELEMENTS: • Visible Text: none • Typography: none • Placement: none STYLE: • Visual Aesthetic: Cinematic, artistic, high fashion photography', NULL, 'lingerie', 'cinematic', NULL, 'https://storage.googleapis.com/prmpt-58b35.firebasestorage.app/prompts/colored-light-bodysuit.webp', NULL, NULL, '[]', '1792932063321');
INSERT OR REPLACE INTO prompts (id, source, source_url, title, abstract, prompt_text, negative_prompt, category, style, model, image_url, width, height, tags, collected_at) VALUES ('prmpt:corset-bathroom-dramatic', 'prmpt', 'https://prmpt.it.com/prompt/corset-bathroom-dramatic', 'Corset Bathroom - Dramatic', 'Dramatic noir boudoir photography with high-contrast lighting. Perfect for lingerie campaigns, intimate fashion editorials, and artistic sensual photography.', 'A young adult woman with naturally styled hair strikes a dramatic arched-back pose, leaning back on a polished marble counter in a dimly lit hotel bathroom. Her slender form is clad in a black lace corset dress adorned with garter straps and thigh-high stockings, complemented by subtle black crystal jewelry reminiscent of Chanel. Harsh low-key evening light casts a narrow beam across her torso, emphasizing the intricate lace texture and the sharp contrast of monochrome shadows enveloping the intimate space. Her hands grip the counter firmly, head tilted upward, while reflections in the mirror deepen the shadow-heavy composition. The shallow focus crisply captures the corset''s delicate fabric against the dark, sensual noir palette, with high-contrast monochrome grain adding tactile richness. The scene conveys a boudoir editorial style, balancing elegance with moody intensity through precise framing and intimate ambiance.', NULL, 'lingerie', 'noir', NULL, 'https://storage.googleapis.com/prmpt-58b35.firebasestorage.app/prompts/corset-bathroom-dramatic.webp', NULL, NULL, '[]', '1792932064899');
INSERT OR REPLACE INTO prompts (id, source, source_url, title, abstract, prompt_text, negative_prompt, category, style, model, image_url, width, height, tags, collected_at) VALUES ('prmpt:elegant-lingerie-lace', 'prmpt', 'https://prmpt.it.com/prompt/elegant-lingerie-lace', 'Elegant Lingerie - Delicate Lace', 'Create elegant intimate fashion shots for lingerie brands, boudoir photography, and intimate apparel campaigns. Tasteful aesthetic perfect for professional intimate photography.', 'Generate elegant and tasteful lingerie, maintaining a classy and sophisticated look. Ensure the style is modern and chic, with delicate lace details and a flattering fit. Keep the overall tone of the image refined and artistic.', NULL, 'lingerie', 'portrait', NULL, 'https://storage.googleapis.com/prmpt-58b35.firebasestorage.app/prompts/elegant-lingerie-lace.webp', NULL, NULL, '[]', '1792932066451');
INSERT OR REPLACE INTO prompts (id, source, source_url, title, abstract, prompt_text, negative_prompt, category, style, model, image_url, width, height, tags, collected_at) VALUES ('prmpt:french-window-vintage-dress', 'prmpt', 'https://prmpt.it.com/prompt/french-window-vintage-dress', 'French Window - Vintage Dress', 'Vintage 70s/80s backless dress photography for retro editorial, romantic campaigns, and cinematic fashion content.', 'Captured from a slightly low and outside vantage point through open French windows, a young Caucasian woman stands with her back gently turned, her posture relaxed yet striking. She wears a white dress characteristic of the era, its plunging back dipping close to the curve of her hips and long fitted sleeves extending gracefully over her hands, showcasing only the faintest tips of fingers when resting softly at her sides or in front. The fabric''s fluid drape speaks of minimalism and elegance, accented by the natural waves of her long brown hair flowing freely down her back, curtain bangs softly framing her face as golden hour sunlight catches loose strands, scattering rich warm hues. She does not meet the camera''s gaze, instead looking down or afar, imparting a quiet mystery and intimate spontaneity as though the moment is candid. The scene is set within an interior opening onto sun-washed walls where amber light wraps around her figure, casting painterly shadows that deepen the dramatic contrast between illuminated surfaces and the darker recesses behind her. The interplay of light and shadow sculpts her silhouette with period-authentic cinematic grace. Embedded 35 mm film grain enriches the tactile texture—from the soft hair waves to the matte fabric and sunlit stucco of the frame—offering the palpable realism and analog feel characteristic of the late 70s and early 80s. The composition, shot with a modest focal length from slightly below eye level, emphasizes natural lines and organic forms with a softly diffused color palette of cream, gold, and muted earth tones. The mood unfolds as dreamy yet charged, a cinematic still that feels both editorial and intimately personal. —late-70s / early-80s cinematic photograph, authentic film grain.', NULL, 'lingerie', 'cinematic', NULL, 'https://storage.googleapis.com/prmpt-58b35.firebasestorage.app/prompts/french-window-vintage-dress.webp', NULL, NULL, '[]', '1792932068012');
INSERT OR REPLACE INTO prompts (id, source, source_url, title, abstract, prompt_text, negative_prompt, category, style, model, image_url, width, height, tags, collected_at) VALUES ('prmpt:french-window-white-dress', 'prmpt', 'https://prmpt.it.com/prompt/french-window-white-dress', 'French Window - White Dress', 'Sensual backless dress photography for luxury fashion, intimate editorial content, and elegant lifestyle campaigns.', 'From a vantage slightly below, a poised young woman stands framed by open French windows, her back teasing the plunging cut of a white dress that slips effortlessly. The fabric flows with delicate grace, long fitted sleeves whispering over relaxed fingertips, tracing minimalist lines that embrace her silhouette with subtle sensuality. Her long brown hair cascades in loose waves, curtain bangs softly framing an intimate, unreadable gaze as strands catch warm sunlight scattering organic warmth across the scene. The room bathes in warm amber hues of golden-hour light pouring obliquely, illuminating whitewashed walls and wrapping her form in painterly glow. Shadows behind settle into quiet obscurity, lending sculptural depth and cinematic gravity to her silhouette. This interplay of light sculpts an atmosphere both private and charged, as if capturing an unguarded whisper beyond the frame. Overlaying the composition, gently textured analog film grain enriches every surface—the soft shimmer of hair, the tactile matte stretch of the fabric, and the rugged sunlit stucco framing the vista. The shot''s subtle motion blur hints at a breath''s imperceptible shift, captured on a medium-format camera with a 85mm lens, head slightly tilted to evoke calm elegance. Together these elements weave a dreamy yet tactile editorial moment, suspended between stillness and organic vitality, suffused with hyper-real texture fidelity and the quiet poise of modern couture elegance—high-fashion editorial, hyper-real texture fidelity.', NULL, 'lingerie', 'portrait', NULL, 'https://storage.googleapis.com/prmpt-58b35.firebasestorage.app/prompts/french-window-white-dress.webp', NULL, NULL, '[]', '1792932069580');
INSERT OR REPLACE INTO prompts (id, source, source_url, title, abstract, prompt_text, negative_prompt, category, style, model, image_url, width, height, tags, collected_at) VALUES ('prmpt:fur-coat-apartment-luxury', 'prmpt', 'https://prmpt.it.com/prompt/fur-coat-apartment-luxury', 'Fur Coat - Apartment Luxury', 'Luxury apartment fashion photography with sophisticated styling. Perfect for high-end fashion brands, editorial content, and upscale lifestyle campaigns.', 'Hyper-realistic editorial lifestyle portrait of a young woman sitting in a modern minimalist apartment interior, captured from a slightly elevated front angle as she lounges in a low designer chair. She is wearing a luxurious black faux-fur coat that drapes around her body and frames her legs, paired with sheer black tights that catch soft reflections from the room light. Her long, straight brown hair flows naturally over her shoulders and down her back, with a subtle side part, adding a sleek, refined look. The background includes a light wooden parquet floor, a simple white wall, a tall narrow mirror to the side, and a mid-century style wooden console with neatly stacked magazines, giving a stylish European apartment vibe. Her pose is relaxed with knees bent toward the camera, one hand resting near her waist under the coat, conveying a slightly mysterious, intimate mood. The overall aesthetic should feel like a candid yet curated fashion snapshot, with a hint of flash photography and understated luxury, no visible brand logos, ultra-detailed realism. Camera: Full-frame DSLR or mirrorless, 50mm or 35mm lens, ISO 200, f/2.2, 1/160s. On-camera or slightly off-camera flash softened with diffusion, evening indoor ambiance. Natural skin texture with visible pores, fine imperfections, subtle freckles. Long straight hair with individual strands visible. Fur coat with rich depth and distinct fibers. Mild HDR-style micro-contrast, soft cinematic color grading, minimal skin retouching, light vignetting, subtle film grain.', NULL, 'lingerie', 'portrait', NULL, 'https://storage.googleapis.com/prmpt-58b35.firebasestorage.app/prompts/fur-coat-apartment-luxury.webp', NULL, NULL, '[]', '1792932071144');
INSERT OR REPLACE INTO prompts (id, source, source_url, title, abstract, prompt_text, negative_prompt, category, style, model, image_url, width, height, tags, collected_at) VALUES ('prmpt:garden-swimsuit-serenity', 'prmpt', 'https://prmpt.it.com/prompt/garden-swimsuit-serenity', 'Garden Serenity - White Swimsuit', 'Authentic lifestyle photography prompt for brand storytelling, social media campaigns, and lifestyle marketing. Natural lighting creates relatable imagery.', 'Sideview of a black woman reclining in a serene garden setting, wearing a sleek white swimsuit. Her skin glistens under soft, her complete body is on the composition, with natural lighting as she closes her eyes, exuding relaxation and peace. Lush greenery surrounds her, with various ferns and tropical plants contributing to a tranquil, verdant atmosphere. There is a leaf in front of the camera, out of focus, creating depth. The image is composed with a slightly elevated angle, focusing on her form and the rich textures of the foliage. The colors are earthy greens and soft whites, enhancing the calming and rejuvenating mood of the scene.', NULL, 'lingerie', 'other', NULL, 'https://storage.googleapis.com/prmpt-58b35.firebasestorage.app/prompts/garden-swimsuit-serenity.webp', NULL, NULL, '[]', '1792932072784');
INSERT OR REPLACE INTO prompts (id, source, source_url, title, abstract, prompt_text, negative_prompt, category, style, model, image_url, width, height, tags, collected_at) VALUES ('prmpt:gothic-mirror-selfie', 'prmpt', 'https://prmpt.it.com/prompt/gothic-mirror-selfie', 'Gothic Mirror Selfie - Silver Hair', 'Gothic fashion selfie photography for alternative brands, social media content, and edgy lifestyle campaigns.', 'SHOT: • Composition: Medium close-up selfie angled downward, mirror reflection visible • Camera Settings: Smartphone camera, likely f/1.8, ISO 400, natural lighting • Film Grain: None LENS EFFECTS: • Optics: Slight wide-angle distortion typical of phone lens • Artifacts: Minimal digital noise • Depth of Field: Shallow, background softly blurred SUBJECT: • Description: Young adult Caucasian female, slim body type, long silver hair flowing • Wardrobe: Shiny black corset-style top with spiderweb pattern, matching black thigh-high stockings, long black gloves • Grooming: Long straight silver hair, smooth skin, subtle makeup SCENE: • Location: Modern interior with wooden flooring and large mirror • Time of Day: Daytime, natural light coming from windows • Environment: Clean, minimalistic indoor space VISUAL DETAILS: • Action: Taking selfie with phone in bunny-eared case, posing with one knee on the floor • Props: Smartphone with white bunny-eared case • Physics: Soft natural light casting gentle shadows CINEMATOGRAPHY: • Lighting: Soft, diffused natural lighting from windows • Tone: Cool, subdued mood • Color Palette: Neutral tones with black and silver accents TEXT ELEMENTS: • Visible Text: None • Typography: None • Placement: None STYLE: • Visual Aesthetic: Modern, sleek, slightly gothic fashion aesthetic', NULL, 'lingerie', 'portrait', NULL, 'https://storage.googleapis.com/prmpt-58b35.firebasestorage.app/prompts/gothic-mirror-selfie.webp', NULL, NULL, '[]', '1792932074364');
INSERT OR REPLACE INTO prompts (id, source, source_url, title, abstract, prompt_text, negative_prompt, category, style, model, image_url, width, height, tags, collected_at) VALUES ('prmpt:lace-lingerie-brown-wall', 'prmpt', 'https://prmpt.it.com/prompt/lace-lingerie-brown-wall', 'Lace Lingerie - Brown Wall', 'Elegant intimate fashion photography with luxurious textures. Perfect for lingerie brands, boudoir photography, and sophisticated intimate apparel campaigns.', 'A lightly tanned blonde woman with soft loose curls and natural makeup stands relaxed, leaning her back against a deep brown wooden paneled wall subtly warmed with reddish undertones. Her hair is gathered into a messy bun, framing a face of precise, sharp cheekbones and tidy, delicate features, accentuating her expressive eyes and natural full lips. She wears an exquisite black lace lingerie set crafted from micro mesh adorned with Gucci-style lace patterns, complemented by thigh-high stockings, a garter belt, and elbow-length gloves, all flawlessly textured. Her slender waist contrasts with voluptuous hips and a full bust, captured in hyperreal detail: skin pores, delicate fabric weave, and the gentle sheen of the material. The setting includes polished parquet flooring beneath her, bathed in luminance that casts a soft warm hue, enriching the tactile richness. Her hands are folded behind her back, face serene and relaxed, embodying confident poise in this intimate, warmly lit portrait.', NULL, 'lingerie', 'portrait', NULL, 'https://storage.googleapis.com/prmpt-58b35.firebasestorage.app/prompts/lace-lingerie-brown-wall.webp', NULL, NULL, '[]', '1792932075936');
