INSERT OR REPLACE INTO prompts (id, source, source_url, title, abstract, prompt_text, negative_prompt, category, style, model, image_url, width, height, tags, collected_at) VALUES ('prmpt:shower-selfie-high-angle', 'prmpt', 'https://prmpt.it.com/prompt/shower-selfie-high-angle', 'Shower Selfie - High Angle', 'Raw candid shower selfie with photorealistic wet skin texture. Perfect for authentic personal photography and unfiltered aesthetic content.', '{
  "subject": {
    "demographics": "Young adult female, light skin tone with visible tan lines.",
    "hair": "Platinum blonde hair with distinct dark roots, styled in a messy high bun, loose strands framing the face.",
    "apparel": "Black strapless bandeau top, minimally visible matching black bottoms.",
    "accessories": "Large silver hoop earrings, thin silver chain necklace with a star pendant.",
    "anatomy": "Full, heavy bust with natural gravitational weight due to forward-leaning pose. Visible cleavage and soft tissue volume. Clear tan lines on the upper chest indicating previous sun exposure with a different top.",
    "skin_details": "Wet, glistening skin texture with visible water droplets. High-resolution pores and skin imperfections. Reflective sheen on shoulders, chest, and face."
  },
  "pose": {
    "body_position": "Deep squatting/crouching position on the floor. Knees bent deeply outward.",
    "orientation": "Facing the camera, body leaning forward.",
    "limbs": "Right arm extended towards the camera (suggesting a selfie angle). Left arm reaching down, hand resting on the floor between the feet.",
    "head_and_gaze": "Head tilted slightly downward, chin tucked. Eyes looking upward directly into the camera lens with a focused expression."
  },
  "environment": {
    "setting": "Tiled shower stall or bathroom corner.",
    "background_elements": "Grey square tiles on walls and floor. Chrome shower mixer/handle visible on the right wall. A white towel hanging on the left side.",
    "surface_interaction": "Floor tiles appear wet. Water reflections visible on the ground."
  },
  "camera": {
    "perspective": "High-angle, top-down perspective (selfie style).",
    "shot_type": "Close-up, full body from a high angle (head to feet visible due to compression).",
    "focal_length": "Wide-angle lens, creating slight perspective distortion where the head and upper body appear larger than the feet.",
    "depth_of_field": "Deep depth of field, keeping both the face and the tiled floor in focus."
  },
  "lighting": {
    "source": "Bright, artificial overhead bathroom lighting.",
    "quality": "Harsh, direct light creating strong specular highlights on the wet skin (forehead, nose, shoulders, chest).",
    "shadows": "Deep, sharp shadows cast by the body onto the floor and under the chin/neck area."
  },
  "mood_and_expression": {
    "emotion": "Candid, intense, slightly provocative but casual.",
    "facial_expression": "Pouting lips, relaxed facial muscles, piercing upward gaze."
  },
  "style_and_realism": {
    "aesthetic": "Raw, unfiltered phone photography. Amateur selfie aesthetic.",
    "fidelity": "Photorealistic, high-fidelity skin texture. No airbrushing or artistic stylization."
  },
  "colors_and_tone": {
    "palette": "Neutral greys (tiles), skin tones (tan and pale), stark black (clothing), silver (accessories).",
    "contrast": "High contrast due to bright overhead light and dark shadows.",
    "saturation": "Natural, slightly muted background with warm skin tones."
  },
  "quality_and_technical_details": {
    "resolution": "High definition, sharp focus.",
    "texture_emphasis": "Emphasis on wet skin, hair strands, and tile grout."
  },
  "aspect_ratio_and_output": {
    "ratio": "3:4",
    "framing": "Vertical orientation."
  }
}', NULL, 'portrait', 'other', NULL, 'https://storage.googleapis.com/prmpt-58b35.firebasestorage.app/prompts/shower-selfie-high-angle.webp', NULL, NULL, '[]', '1792932207225');
