INSERT OR REPLACE INTO prompts (id, source, source_url, title, abstract, prompt_text, negative_prompt, category, style, model, image_url, width, height, tags, collected_at) VALUES ('prmpt:late-70s-velvet-lounge', 'prmpt', 'https://prmpt.it.com/prompt/late-70s-velvet-lounge', 'Late 70s - Velvet Lounge', 'Vintage 70s/80s fashion photography for retro campaigns, nostalgic editorial content, and cinematic portrait work.', 'late-70s / early-80s cinematic fashion photograph, subtly sexy and sensual but tasteful, of a young Caucasian woman with an average frame reclining more languidly on a burnt-orange velvet banquette in a softly dimmed lounge with warm mahogany walls. She wears a deep red halter mini-dress with a subtle shimmer, the dress riding slightly higher on her thighs to reveal more leg while remaining classy, open back suggested by the halter cut. Long dark brown hair falls freely over her shoulders with curtain bangs framing her face, her expression soft and sultry with a faint, knowing smile, eyes half-lidded, head slightly tilted toward camera. She crosses her legs in a relaxed but alluring pose, one heel slipped halfway out of her shoe, body language confident and inviting. Overhead warm tungsten lighting and slender brass picture lights above gilded pastoral paintings cast a golden haze, creating deliberate chiaroscuro that sculpts her silhouette, accentuates the curves of her body, and reveals the tactile textures of velvet upholstery, polished wood grain, and the delicate contours of her features, while areas of shadow dissolve into mystery. Nearby, a black lacquered table reflects faint glints from the ambient glow, amplifying the room''s painterly obscurity. Rich tactile surfaces, shimmering fabric, polished wood, softened shadows, intimate vintage tableau with heightened sensuality. Captured on 35mm film stock reminiscent of Kodachrome, warm saturated hues, fine authentic analog film grain, slight halation around highlights, framed at mid-chest eye level with a classic 50mm lens, poised formality with intimate immediacy, editorial glamour of late-70s fashion photography, baroque-inspired interior details, authentic vintage fidelity, cinematic photograph, baroque interior mood', NULL, 'lingerie', 'cinematic', NULL, 'https://storage.googleapis.com/prmpt-58b35.firebasestorage.app/prompts/late-70s-velvet-lounge.webp', NULL, NULL, '[]', '1792939225967');
