INSERT OR REPLACE INTO prompts (id, source, source_url, title, abstract, prompt_text, negative_prompt, category, style, model, image_url, width, height, tags, collected_at) VALUES ('prmpt:lingerie-stairs-luxury-boudoir', 'prmpt', 'https://prmpt.it.com/prompt/lingerie-stairs-luxury-boudoir', 'Lingerie Stairs - Luxury Boudoir', 'Luxurious boudoir fashion on ornate staircase. Perfect for high-end lingerie campaigns, elegant intimate fashion, and sophisticated sensual photography.', 'Soft daylight filters through a window, casting warm hues across an ornate wooden staircase adorned with a rich carpet runner. A slim young woman, draped in a black lace lingerie set featuring corset lacing, a garter belt, and thigh-high stockings, descends the steps with a confident strut. A luxurious fur stole cascades gently with her motion, while layered Chanel-style chains and double-C pendants shimmer subtly against the warm interior tones. Her polished glam makeup enhances a composed expression as black sunglasses obscure her eyes, lending an air of mystery. One hand grazes the carved railing, emphasizing graceful movement. The camera''s telephoto compression gently softens the carved wood and framed mirror behind her, while a moderate depth of field keeps her sharply focused. Soft natural side light complemented by a delicate fill flash sculpts her silhouette, illuminating the textures of lace and fur. The image exudes a high-fashion boudoir runway moment, radiating luxury, confidence, and seduction in every detail.', NULL, 'lingerie', 'portrait', NULL, 'https://storage.googleapis.com/prmpt-58b35.firebasestorage.app/prompts/lingerie-stairs-luxury-boudoir.webp', NULL, NULL, '[]', '1792939228821');
