INSERT OR REPLACE INTO prompts (id, source, source_url, title, abstract, prompt_text, negative_prompt, category, style, model, image_url, width, height, tags, collected_at) VALUES ('prmpt:night-city-devil-costume', 'prmpt', 'https://prmpt.it.com/prompt/night-city-devil-costume', 'Night City - Devil Costume', 'Cinematic night photography for Halloween content, costume campaigns, and moody urban editorial work.', 'Medium close-up side profile photograph of a young adult Caucasian woman with a slim body type and long dark hair, seated inside a car at night. She wears a sexy black winged costume with black feathered wings, a devil horns headband, sheer black fishnet gloves, and a tight, low-cut partially unzipped black top with noticeable cleavage, along with fishnet tights. She has a pensive yet subtly seductive expression, long smooth hair, and subtle makeup with winged eyeliner. She sits calmly looking out the car window to the side. Outside the windows, a night city street with blurred traffic lights and vehicles is visible. Fine film grain, low light look with ISO 3200 feel, wide aperture f/1.8, moderate shutter speed. Slight lens flare from car lights, shallow depth of field with the subject in sharp focus and the background heavily blurred. Reflections and light scattering on the glass surfaces. Neon red and cool ambient street lighting mix, soft shadows, backlit hair highlights. Dramatic, moody, slightly mysterious tone, modern urban fantasy, high-contrast cinematic night photography, tasteful but clearly sensual wardrobe emphasizing chest neckline.', NULL, 'lingerie', 'cinematic', NULL, 'https://storage.googleapis.com/prmpt-58b35.firebasestorage.app/prompts/night-city-devil-costume.webp', NULL, NULL, '[]', '1792939246426');
