INSERT OR REPLACE INTO prompts (id, source, source_url, title, abstract, prompt_text, negative_prompt, category, style, model, image_url, width, height, tags, collected_at) VALUES ('prmpt:outdoor-shower-bikini', 'prmpt', 'https://prmpt.it.com/prompt/outdoor-shower-bikini', 'Outdoor Shower - Brazilian Bikini', 'Outdoor lifestyle swimwear photography for resort brands, travel content, and summer campaign imagery.', 'Full-body rear view of a young adult Caucasian woman with a slim, curvy Brazilian-style lower body, toned legs and rounded hips, wet black loosely wavy hair reaching to her upper back, standing under an outdoor shower. She is in a confident, sexy but tasteful pose from behind, one hip popped, weight on one leg, the other leg slightly bent, back subtly arched, one arm reaching up toward the shower fixture or her hair, the other arm relaxed by her side. She is wearing a minimalistic black Brazilian bikini: a small triangle top and a very minimal Brazilian-cut bottom with thin side straps and narrow back coverage, clearly showing the shape of her legs and hips while remaining non-explicit. Natural stone walls form the shower area, with a stainless steel shower fixture above her and water spraying down, droplets on her skin and wet stone surfaces. Clear blue sky and green foliage visible at the top edges of the walls. Shot at midday in strong natural sunlight, with bright highlights and defined shadows. Realistic, candid outdoor lifestyle photography, moderate depth of field with the subject in clear focus and the stone background slightly blurred, slight wide-angle lens feel, no film grain, vibrant warm earth tones, black swimwear, bright blue sky and green leaves.', NULL, 'lingerie', 'film', NULL, 'https://storage.googleapis.com/prmpt-58b35.firebasestorage.app/prompts/outdoor-shower-bikini.webp', NULL, NULL, '[]', '1792939248328');
