INSERT OR REPLACE INTO prompts (id, source, source_url, title, abstract, prompt_text, negative_prompt, category, style, model, image_url, width, height, tags, collected_at) VALUES ('prmpt:pink-lingerie-cake-studio', 'prmpt', 'https://prmpt.it.com/prompt/pink-lingerie-cake-studio', 'Pink Lingerie - Cake Studio', 'Soft pastel studio photography with playful cake aesthetic. Perfect for lifestyle brands, sweet fashion content, and contemporary editorial photography.', 'Soft, even frontal and slightly overhead studio lighting casts gentle highlights over a young adult Caucasian female seated on a seamless gray floor, dressed in pale pink lace-trimmed nightwear with matching shorts and white ankle socks striped in soft pink. Her relaxed yet elevated posture holds a cream and pink decorated cake topped with fresh cherries, while two similarly adorned cakes rest nearby, accompanied by naturally scattered cherries enhancing a playful aesthetic. A delicate pearl chain with a tiny double-C charm subtly encircles her waist, complementing natural glamorous makeup featuring light blush and lips slightly parted in a neutral expression. The minimalist indoor studio backdrop blurs softly beyond moderate depth of field, emphasizing crisp focus on her and the desserts. The color palette weaves grays, soft pinks, creams, and vivid red accents, unified by a moderate cinematic film grain evoking the texture of 35mm film, lending the contemporary fashion editorial portrait a stylish, raw finish.', NULL, 'lingerie', 'cinematic', NULL, 'https://storage.googleapis.com/prmpt-58b35.firebasestorage.app/prompts/pink-lingerie-cake-studio.webp', NULL, NULL, '[]', '1792939253596');
INSERT OR REPLACE INTO prompts (id, source, source_url, title, abstract, prompt_text, negative_prompt, category, style, model, image_url, width, height, tags, collected_at) VALUES ('prmpt:pool-table-bodysuit', 'prmpt', 'https://prmpt.it.com/prompt/pool-table-bodysuit', 'Pool Table - Bodysuit', 'Neo-noir bodysuit photography for luxury lingerie campaigns, vintage editorial content, and cinematic fashion imagery.', 'A young Caucasian woman reclines languidly across the rich emerald felt of a vintage pool table, her body stretched out diagonally with an effortless yet commanding grace. Dressed in a fitted nude-toned bodysuit that contours each curve with sleek minimalism, she props herself up on one elbow while her other hand grazes her glossy parted lips, a gesture both playful and seductively inviting. Her legs bend upward behind her, accentuated by striking scarlet stiletto heels that catch the overhead lighting with a vivid, almost liquid gleam, creating a sharp, vibrant contrast against the deep green surface beneath her. Around her neck coils a classic string of pearls, shimmering softly with old-Hollywood sophistication, while large rings and subtle fine jewelry glint gently in the focused light, weaving an aura of indulgent luxury around her. Her loose, voluminous waves are partially pulled back, the soft texture catching hints of the stark illumination, complementing smoky eye makeup and sculpted cheekbones that frame her relaxed yet intense expression. Three harsh overhead lamps cast pools of dramatic light that spotlight the woman and the pool table, the scene framed by deep shadows swallowing the rest of the room into near-total darkness. The high-contrast lighting sculpts her silhouette into sharp relief against the saturated colors, the atmosphere thick with noir seduction and editorial glamour that feels both cinematic and dangerously intimate. Captured at a slightly elevated, mid-shot vantage using a classic 50mm focal length on 35mm film stock, this composition reveals textured analog grain and gate weave, tactile with the velvet felt''s weave and the gleam of patent leather heels—invoking the mood and style of a neo-noir 1980s fashion campaign. —late-70s / early-80s cinematic photograph, authentic film grain.', NULL, 'lingerie', 'cinematic', NULL, 'https://storage.googleapis.com/prmpt-58b35.firebasestorage.app/prompts/pool-table-bodysuit.webp', NULL, NULL, '[]', '1792939254065');
INSERT OR REPLACE INTO prompts (id, source, source_url, title, abstract, prompt_text, negative_prompt, category, style, model, image_url, width, height, tags, collected_at) VALUES ('prmpt:porsche-hood-fashion-editorial', 'prmpt', 'https://prmpt.it.com/prompt/porsche-hood-fashion-editorial', 'Porsche Hood - Fashion Editorial', 'Fashion editorial portrait on a classic Porsche hood with dramatic sunlight and car culture aesthetic. Perfect for automotive fashion crossover content, luxury lifestyle photography, and iconic editorial shoots.', '{
