    "body_type": "slim hourglass figure with long legs, toned yet feminine proportions, smooth flawless skin"
  },
  "pose_and_composition": {
    "pose": "lying reclined on the hood of a black sports car, body stretched out diagonally with legs extended toward front, right arm raised with hand resting on forehead in shielding/dramatic gesture, left arm relaxed by side, head tilted slightly back for sensual and relaxed vibe",
    "framing": "medium full-body shot from mid-thigh up, low-angle perspective emphasizing the car hood and subject dominance, vertical portrait orientation with car filling lower frame"
  },
  "clothing_and_details": {
    "swimsuit": "sleek white high-cut one-piece bodysuit or swimsuit with deep scoop neckline, minimalist design featuring small black ''Melisa'' logo text centered on chest, smooth matte fabric clinging to body",
    "accessories": "small hoop earrings, no other visible jewelry",
    "overall_style": "minimalist high-fashion swimwear with branded logo, elegant and provocative"
  },
