INSERT OR REPLACE INTO prompts (id, source, source_url, title, abstract, prompt_text, negative_prompt, category, style, model, image_url, width, height, tags, collected_at) VALUES ('prmpt:summer-wall-bikini-cards', 'prmpt', 'https://prmpt.it.com/prompt/summer-wall-bikini-cards', 'Summer Wall - Bikini &amp; Cards', 'Retro summer swimwear photography for lifestyle brands, vacation content, and nostalgic editorial campaigns.', 'SHOT: • Composition: Relaxed medium full-body shot, leaning against a whitewashed wall • Camera Settings: ISO 200, f/4.0, 1/500 s • Film Grain: Soft, retro film grain effect LENS EFFECTS: • Optics: Standard lens with warm color rendering • Artifacts: Slight vignette, emphasizing subject • Depth of Field: Moderate, subject sharp with softly blurred background SUBJECT: • Description: Young adult Caucasian female, average body type, laid-back expression • Wardrobe: Minimal string bikini, baseball cap shading face SCENE: • Location: Sun-drenched exterior against whitewashed wall • Time of Day: Late afternoon golden hour • Environment: Long shadows, warm sunlight VISUAL DETAILS: • Action: Leaning casually, sipping from soda cup with straw in one hand, holding playing cards in the other • Props: Soda cup, playing cards, baseball cap • Physics: Relaxed posture, natural sunlight casting long shadows and warm highlights CINEMATOGRAPHY: • Lighting: Cinematic warm golden-hour light, retro summery mood • Tone: Sensual, effortless, candid editorial style • Color Palette: Warm tones, golden sunlight, soft shadows, natural skin tones TEXT ELEMENTS: • Visible Text: Soda cup branding partially visible • Typography: Standard commercial font • Placement: On soda cup held in one hand STYLE: • Visual Aesthetic: Retro summer editorial photography, sensual lifestyle vibe with cinematic warmth', NULL, 'lingerie', 'cinematic', NULL, 'https://storage.googleapis.com/prmpt-58b35.firebasestorage.app/prompts/summer-wall-bikini-cards.webp', NULL, NULL, '[]', '1792939269299');
INSERT OR REPLACE INTO prompts (id, source, source_url, title, abstract, prompt_text, negative_prompt, category, style, model, image_url, width, height, tags, collected_at) VALUES ('prmpt:summer-wall-wine-bikini', 'prmpt', 'https://prmpt.it.com/prompt/summer-wall-wine-bikini', 'Summer Wall - Wine &amp; Bikini', 'Summer lifestyle editorial for swimwear brands, wine campaigns, and sensual vacation content with vintage aesthetic.', 'A young woman reclines gracefully against a whitewashed wall layered with weathered paint that breathes authentic texture. Honeyed sunlight spills across her figure, stretching soft shadows and illuminating the subtle woven intricacy of her loose, white baggy t-shirt draped over a minimalist string bikini. A relaxed baseball cap shades her poised face, casting natural contours in serene shadow, imbuing the moment with an intimate but polished sensuality. She holds a wine glass with languid ease, embodying candid sophistication. The warmth of a retro summer palette suffuses the scene—amber and ochre hues diffuse gentle backlight, sculpting her silhouette and lending depth to skin and fabric textures. A subdued vintage film grain overlays this analog reverie, rendering a palpable tactile authenticity that enriches the editorial resonance. The soft atmosphere bathes her in golden light, amplifying the relaxed mood through nuanced shadow play. Captured at eye level with a balanced moderate focal length, the tightly cropped frame centers the nuanced gesture and texture interplay. Directional natural light carves genuine skin tones, caresses fabric ripples, and sculpts shadows that both define and unify form and surface, creating a palpable three-dimensionality. The composition channels the warmth and ease of summer fashion filtered through an editorial cinematic eye. This portrait embraces relaxed candor fused with eloquent refinement, presenting a visceral visual narrative steeped in texture and mood—a hyper-real testament to luminous natural light and tactile detail—high-fashion editorial, hyper-real texture fidelity', NULL, 'lingerie', 'cinematic', NULL, 'https://storage.googleapis.com/prmpt-58b35.firebasestorage.app/prompts/summer-wall-wine-bikini.webp', NULL, NULL, '[]', '1792939269768');
