INSERT OR REPLACE INTO prompts (id, source, source_url, title, abstract, prompt_text, negative_prompt, category, style, model, image_url, width, height, tags, collected_at) VALUES ('prmpt:white-bikini-desert-relaxation', 'prmpt', 'https://prmpt.it.com/prompt/white-bikini-desert-relaxation', 'White Bikini - Desert Relaxation', 'Serene outdoor lifestyle photography with natural setting. Perfect for resort content, wellness brands, and relaxation-focused lifestyle campaigns.', 'A woman in a white bikini relaxes outdoors, enjoying the sunshine in a serene setting. The primary focus is a woman with short, balayage hair. She is wearing a white string bikini. Her body appears toned, and she has a tan. She is positioned sitting on a low stone or concrete structure. The background suggests an outdoor, possibly desert-like environment. There''s a low, adobe-style building or wall behind her. A wooden pergola or frame is visible, and beyond that, a glimpse of hills or a distant landscape. There''s a hammock strung up, suggesting a relaxation area. A small tree or bush is located on her left, adding a natural element to the scene. The overall atmosphere is relaxed and serene. The bright sunlight and clear sky evoke a sense of warmth and leisure. The woman''s posture and distant gaze suggest a moment of contemplation and enjoyment of the surroundings. The scene feels tranquil and idyllic.', NULL, 'lingerie', 'landscape', NULL, 'https://storage.googleapis.com/prmpt-58b35.firebasestorage.app/prompts/white-bikini-desert-relaxation.webp', NULL, NULL, '[]', '1792939283202');
