INSERT OR REPLACE INTO prompts (id, source, source_url, title, abstract, prompt_text, negative_prompt, category, style, model, image_url, width, height, tags, collected_at) VALUES ('prmpt:white-lace-legs-spread-chair', 'prmpt', 'https://prmpt.it.com/prompt/white-lace-legs-spread-chair', 'White Lace - Legs Spread Chair', 'Generate contemporary lingerie photography for high-end brands, editorial content, and professional boudoir work. Expert lighting ensures sophisticated results.', 'A provocative high-fashion editorial photograph of a confident woman sitting in a modern minimalist chair with her legs spread wide apart in a bold, inviting pose. She wears delicate white lace lingerie and leans back with one hand behind her head, the other resting on her thigh. Her expression is intense and seductive with direct eye contact. Shot in a luxury studio with dramatic side lighting creating strong shadows and highlights on her body. 85mm lens, f/2.0. Moody color grading with cool blue and warm amber tones mixing. The composition is unapologetically sensual and empowering, inspired by provocative lingerie brand campaigns. Professional editorial quality with artistic lighting.', NULL, 'lingerie', 'minimalist', NULL, 'https://storage.googleapis.com/prmpt-58b35.firebasestorage.app/prompts/white-lace-legs-spread-chair.webp', NULL, NULL, '[]', '1792939284136');
