INSERT OR REPLACE INTO prompts (id, source, source_url, title, abstract, prompt_text, negative_prompt, category, style, model, image_url, width, height, tags, collected_at) VALUES ('prmpt:y2k-bikini-collage-arcade', 'prmpt', 'https://prmpt.it.com/prompt/y2k-bikini-collage-arcade', 'Y2K Bikini - 4-Panel Collage', 'Y2K aesthetic 4-panel photo collage with neon bikini and flash photography. Perfect for nostalgic social media content, Y2K fashion campaigns, and playful collage-style photography.', 'A 4-panel 2x2 photo collage in a 4:5 aspect ratio, styled like a casual social media snapshot with a Y2K aesthetic and direct flash photography. The subject is a young Caucasian American blonde woman with a slim, athletic build and a light warm sun-kissed skin tone. She has long, wavy blonde hair with subtle honey highlights, styled in a messy half-up high pony or playful pigtails, with loose face-framing strands and a slightly tousled look. Her face is heart-shaped to oval with almond-shaped blue-green eyes, winged eyeliner, natural groomed brows, a small button nose, full glossy pink lips, and rosy flushed cheeks with heavy blush for a youthful glow. She is wearing a two-piece string bikini in neon magenta (hot pink) and bright turquoise/seafoam green, featuring a green lace or patterned overlay with solid neon pink trim and straps. The top is a triangle halter style and the bottoms are low-rise side-tie strings. Accessories include a beaded choker necklace with white, turquoise, and metallic beads, an anklet on her left ankle, and platform slides/sandals visible in one frame. Panel poses: Top left: full body, leaning back against a wall with one leg bent and lifted, left hand making a shaka sign, winking with a slight smile and tongue lightly pressing teeth. Top right: waist-up, facing forward, holding the ends of her hair outward, making a duck-face pout and looking to the side. Bottom left: full body, legs shoulder-width and knees slightly bent, double peace signs near her eyes, playful pout/kiss face with eyes closed or squinting. Bottom right: waist-up, arms raised with hands resting on her head, soft gaze at the camera, mouth slightly open with a relaxed, alluring expression. The setting is an indoor stairwell or hallway landing with plain light blue-grey or cool mint walls, a white dual light switch plate, a white painted wooden handrail on the right, beige/light grey carpet, and white baseboards. Lighting is bright on-camera flash creating sharp shadows and high contrast, like indoor artificial flash photography.', NULL, 'lifestyle', 'noir', NULL, 'https://storage.googleapis.com/prmpt-58b35.firebasestorage.app/prompts/y2k-bikini-collage-arcade.webp', NULL, NULL, '[]', '1792939287463');
